import {
  Host,
  h,
  Component,
  State,
  Prop,
  Element,
  Event,
  type ComponentInterface,
  type EventEmitter,
} from '@stencil/core';
import { sendActionTracking } from '@src/shared/unclassified/tracking';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { Uncontrollable } from '@src/framework/decorators';

const PREFIX = 'chip';

/**
 * @slot default - Label or custom content rendered inside the chip.
 * @slot prefix - The slot for the prefix content.
 * @part base - The base container of the component.
 * @part label - The label element.
 */
@Component({
  tag: 'ks-chip',
  styleUrl: 'ks-chip.scss',
  shadow: true,
})
export class KsChip implements ComponentInterface {
  static vModel = { prop: 'selected', event: 'ksChange' };
  @Element() el!: HTMLKsChipElement;

  private isControlled = false;

  /** Indicates whether the chip is disabled. If set to `true`, the chip will be not clickable and visually indicate its disabled state. */
  @Prop() disabled = false;
  /** Indicates whether the chip is selected. */
  @Prop() selected?: boolean;
  /** Indicates whether the chip is selected by default. */
  @Prop() defaultSelected?: boolean;

  @Uncontrollable('selected', 'defaultSelected', 'ksChange') @State() internalSelected?: boolean;

  /** Emits when the chip's selected state changes. The event carries a boolean value indicating the new selected state. */
  @Event() ksChange!: EventEmitter<boolean>;

  constructor() {
    registerPluginManager(this.el);
  }

  private handleClick = () => {
    if (this.disabled) return;

    const nextSelected = !this.internalSelected;

    if (!this.isControlled) {
      this.internalSelected = nextSelected;
    }

    this.ksChange.emit(nextSelected);
    sendActionTracking(this.el, { eventType: 'change', componentParams: { value: nextSelected } });
  };

  render() {
    const { internalSelected, disabled } = this;

    return (
      <Host class="KsChip">
        <div
          class={{
            [PREFIX]: true,
            [`${PREFIX}--active`]: !!internalSelected,
            [`${PREFIX}--disabled`]: disabled,
          }}
          onClick={this.handleClick}
          data-testid="ks-chip-ks-chip-n9wDKu"
          part="base"
        >
          <slot name="prefix" />
          <span class={`${PREFIX}-label`} part="label">
            <slot></slot>
          </span>
        </div>
      </Host>
    );
  }
}
